const input = $input.first().json;
const prevData = $('Validation').first().json;

const data = input.body || input;
const apiJobId = data.job_id || prevData.jobId;

return [{
  json: {
    ...prevData,
    jobId: apiJobId
  }
}];

const input = $input.first().json;
// Get validation data - try multiple paths for async vs sync flow
let prevData;
try {
  prevData = $('Extract Job ID').first().json;
} catch (e) {
  prevData = $('Validation').first().json;
}

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Verifier erreur OCR
if (statusCode >= 400) {
  return [{
    json: {
      ...prevData,
      ocrSuccess: false,
      ocrError: data.message || data.error?.message || 'Mistral API error: ' + statusCode
    }
  }];
}

const ocrText = data.choices?.[0]?.message?.content || '';

if (!ocrText) {
  return [{
    json: {
      ...prevData,
      ocrSuccess: false,
      ocrError: 'OCR returned empty content'
    }
  }];
}

return [{
  json: {
    ...prevData,
    ocrText: ocrText,
    ocrSuccess: true,
    workerPayload: {
      job_id: prevData.jobId,
      text: ocrText,
      source_language: prevData.sourceLanguage === 'auto' ? 'he' : prevData.sourceLanguage,
      target_language: prevData.targetLanguage,
      api_key: prevData.anthropicApiKey,
      openai_api_key: prevData.openaiApiKey,
      job_type: 'pdf_translation',
      metadata: {
        source: 'pdf_layout_translator',
        ocr_model: 'pixtral-12b-2409'
      }
    }
  }
}];

// Le worker gere la traduction et met a jour le job
const prevData = $('Extract OCR + Prepare Worker').first().json;

console.log('PDF Translation job dispatched:', prevData.jobId);

return [{
  json: {
    jobId: prevData.jobId,
    status: 'processing',
    ocrCompleted: true,
    translationStarted: true,
    callbackUrl: prevData.callbackUrl,
    hasCallback: prevData.hasCallback,
    ocrText: prevData.ocrText
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

const crypto = require('crypto');
const prevData = $input.first().json;

// Build callback payload (RFC-040)
const body = {
  success: true,
  job_id: prevData.jobId,
  status: 'completed',
  result: {
    ocr_completed: true,
    translation_started: true,
    ocr_text_length: prevData.ocrText?.length || 0
  }
};

// HMAC Signature (RFC-040 format)
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callbackUrl: prevData.callbackUrl,
    body: body,
    signature: signature
  }
}];

// Prepare error data for callback check
const prevData = $('Extract OCR + Prepare Worker').first().json;

return [{
  json: {
    jobId: prevData.jobId,
    ocrError: prevData.ocrError,
    callbackUrl: prevData.callbackUrl,
    hasCallback: prevData.hasCallback
  }
}];

const crypto = require('crypto');
const prevData = $input.first().json;

// Build error callback payload (RFC-040)
const body = {
  success: false,
  job_id: prevData.jobId,
  status: 'failed',
  error: {
    code: 'OCR_FAILED',
    message: prevData.ocrError || 'OCR processing failed'
  }
};

// HMAC Signature (RFC-040 format)
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callbackUrl: prevData.callbackUrl,
    body: body,
    signature: signature
  }
}];
